mapper.select:

where merged_into is null and del_flag = '0'
and stage = #{stage}
and first_source = #{firstSource}
and first_channel = #{firstChannel}
and minor = #{minor}
and grade = #{grade}
and display_name like concat('%', #{params.keyword}, '%')
and phone_hash = #{params.phoneHash}
and first_touch_time >= cast(#{params.beginTime} as date)
and first_touch_time < cast(#{params.endTime} as date) + interval '1 day'
and owner_user_id = #{ownerUserId}
and owner_user_id is null
and next_follow_time is not null and next_follow_time <= now() and stage not in ('won', 'lost')
order by case grade when 'A' then 1 when 'B' then 2 when 'C' then 3 else 4 end, next_follow_time nulls last, last_touch_time desc, lead_id desc


where del_flag = '0' and (false
or app_user_id = #{appUserId}
or unionid = #{unionid}
or phone_hash = #{phoneHash}
)
order by lead_id
